function overAThird(nums: number[]): number[] {
  const out: number[] = [];
  for (const x of nums) {
    if (out.includes(x)) continue;
    let c = 0;
    for (const y of nums) if (y === x) c++;
    if (c > Math.floor(nums.length / 3)) out.push(x);
  }
  return out;
}

