function overAThird(nums: number[]): number[] {
  const cnt = new Map<number, number>();
  for (const x of nums) cnt.set(x, (cnt.get(x) ?? 0) + 1);
  const limit = Math.floor(nums.length / 3);
  return [...cnt].filter(([, c]) => c > limit).map(([v]) => v);
}

