function overAThird(nums: number[]): number[] {
  let c1 = 0, n1 = 0, c2 = 1, n2 = 0;
  for (const x of nums) {
    if (n1 > 0 && x === c1) n1++;
    else if (n2 > 0 && x === c2) n2++;
    else if (n1 === 0) { c1 = x; n1 = 1; }
    else if (n2 === 0) { c2 = x; n2 = 1; }
    else { n1--; n2--; }
  }
  const out: number[] = [];
  const limit = Math.floor(nums.length / 3);
  for (const c of c1 === c2 ? [c1] : [c1, c2]) {
    let k = 0;
    for (const x of nums) if (x === c) k++;
    if (k > limit) out.push(c);
  }
  return out;
}

