    def overAThird(self, nums: List[int]) -> List[int]:
        c1, n1, c2, n2 = 0, 0, 1, 0
        for x in nums:
            if n1 > 0 and x == c1:
                n1 += 1
            elif n2 > 0 and x == c2:
                n2 += 1
            elif n1 == 0:
                c1, n1 = x, 1
            elif n2 == 0:
                c2, n2 = x, 1
            else:
                n1 -= 1
                n2 -= 1
        limit = len(nums) // 3
        cands = [c1] if c1 == c2 else [c1, c2]
        return [c for c in cands if nums.count(c) > limit]

